-- HRPayrollCore 009d - integrated payroll engine + review breakdown
-- Uses effective worker classification and Tier 3 organization setup during calculation.
-- Adds review snapshot columns; historical posted runs are not recalculated.

alter table public.payroll_run_employees
 add column if not exists allowances_total numeric(14,2) not null default 0,
 add column if not exists overtime_total numeric(14,2) not null default 0,
 add column if not exists bonus_total numeric(14,2) not null default 0,
 add column if not exists arrears_other_earnings numeric(14,2) not null default 0,
 add column if not exists loan_deductions numeric(14,2) not null default 0,
 add column if not exists other_nonloan_deductions numeric(14,2) not null default 0;

create or replace function public.payroll_calculate_run(p_tenant uuid,p_period uuid)
returns uuid language plpgsql security definer set search_path=public as $$
declare r uuid; rn text; rec record; re uuid; pend date; country text; pr public.payroll_pension_rules%rowtype;
 basic numeric; earn numeric; ded numeric; taxable_extra numeric; pretax numeric; gross numeric; taxable numeric; insurable numeric; emp_pen numeric; er_pen numeric; tier1 numeric; tier2 numeric;
 pf_emp numeric; pf_er numeric; relief numeric; cfg jsonb; cls record; org_pf_emp numeric; org_pf_er numeric; pf_emp_rate numeric; pf_er_rate numeric; tier3_ok boolean; rel text; pension_mode text; tax_mode text; allowances numeric; loans numeric; chargeable numeric; tx numeric; net numeric; adjearn numeric; adjded numeric; adjpretax numeric; bonus_amt numeric; overtime_amt numeric; normal_adj_earn numeric; ot_tax numeric; bonus_tax numeric; bonus_concession numeric;
begin
 if not public.has_tenant_role(p_tenant,array['owner','administrator','payroll_manager','payroll_officer']) then raise exception 'Payroll access denied'; end if;
 select end_date into pend from public.payroll_periods where id=p_period and tenant_id=p_tenant; if pend is null then raise exception 'Invalid payroll period'; end if;
 select coalesce(country_code,'GH') into country from public.payroll_settings where tenant_id=p_tenant; country:=coalesce(country,'GH');
 select * into pr from public.payroll_pension_rules x where x.country_code=country and x.active and x.effective_from<=pend and (x.effective_to is null or x.effective_to>=pend) and (x.tenant_id=p_tenant or x.tenant_id is null) order by (x.tenant_id is not null) desc,x.effective_from desc limit 1;
 select coalesce(config,'{}'::jsonb) into cfg from public.payroll_setup_configs where tenant_id=p_tenant and lower(section)='tier3' limit 1; cfg:=coalesce(cfg,'{}'::jsonb);
 if country='GH' and not exists(select 1 from public.payroll_tax_bands b where b.country_code='GH' and b.active and b.effective_from<=pend and (b.effective_to is null or b.effective_to>=pend) and (b.tenant_id=p_tenant or b.tenant_id is null)) then raise exception 'No effective PAYE bands configured for payroll period end %',pend; end if;
 select id into r from public.payroll_runs where tenant_id=p_tenant and period_id=p_period;
 if r is null then rn:='RUN-'||to_char(pend,'YYYYMM')||'-'||lpad((1+(select count(*) from public.payroll_runs where tenant_id=p_tenant))::text,3,'0'); insert into public.payroll_runs(tenant_id,period_id,run_no,status,created_by) values(p_tenant,p_period,rn,'draft',auth.uid()) returning id into r;
 else if exists(select 1 from public.payroll_runs where id=r and status in ('approved','posted')) then raise exception 'Approved/posted payroll cannot be recalculated'; end if; delete from public.payroll_run_employees where run_id=r; end if;
 for rec in select e.*,pp.tax_residency,pp.worker_tax_category,pp.staff_category,pp.pension_tier1_enabled,pp.pension_tier2_enabled,pp.provident_fund_enabled,pp.provident_employee_rate,pp.provident_employer_rate,pp.tier3_participation_mode,pp.provident_effective_from,pp.provident_effective_to from public.hr_employees e join public.payroll_profiles pp on pp.employee_id=e.id and pp.active where e.tenant_id=p_tenant and e.employment_status='active' loop
  select c.* into cls from public.payroll_worker_classifications c where c.tenant_id=p_tenant and c.employee_id=rec.id and c.effective_from<=pend and (c.effective_to is null or c.effective_to>=pend) order by c.effective_from desc limit 1;
  rel:=coalesce(cls.employment_relationship,case when lower(coalesce(rec.employment_type,'regular'))='permanent' then 'regular' else lower(coalesce(rec.employment_type,'regular')) end);
  tax_mode:=coalesce(cls.tax_treatment,case when tax_mode='non_resident' then 'non_resident' when rec.worker_tax_category='casual' then 'casual_worker' when rec.worker_tax_category='temporary' then 'temporary_worker' else 'standard_paye' end);
  pension_mode:=coalesce(cls.pension_status,'active_contributor');
  if pension_mode='pending_review' then raise exception 'Payroll blocked: % (%) pension status is Pending Review',concat_ws(' ',rec.first_name,rec.last_name),rec.employee_no; end if;
  select coalesce((select sh.new_salary from public.hr_salary_history sh where sh.employee_id=rec.id and sh.effective_from<=pend order by sh.effective_from desc,sh.created_at desc limit 1),(select c.basic_salary from public.hr_employment_contracts c where c.employee_id=rec.id and c.status='active' order by c.start_date desc limit 1),0) into basic;
  select coalesce(sum(case when pc.component_type='earning' then pec.amount else 0 end),0),coalesce(sum(case when pc.component_type='deduction' then pec.amount else 0 end),0),coalesce(sum(case when pc.component_type='earning' and pc.taxable then pec.amount else 0 end),0),coalesce(sum(case when pc.component_type='deduction' and pc.pre_tax then pec.amount else 0 end),0) into earn,ded,taxable_extra,pretax from public.payroll_employee_components pec join public.payroll_components pc on pc.id=pec.component_id where pec.employee_id=rec.id and pec.tenant_id=p_tenant and pec.effective_from<=pend and (pec.effective_to is null or pec.effective_to>=pend) and pc.code<>'BASIC';
  select coalesce(sum(case when adjustment_type in ('earning','arrears') then amount else 0 end),0),coalesce(sum(case when adjustment_type in ('deduction','loan','unpaid_absence') then amount else 0 end),0),coalesce(sum(case when adjustment_type='pre_tax_deduction' then amount else 0 end),0),coalesce(sum(case when adjustment_type='bonus' then amount else 0 end),0),coalesce(sum(case when adjustment_type='overtime' then amount else 0 end),0) into normal_adj_earn,adjded,adjpretax,bonus_amt,overtime_amt from public.payroll_adjustments where tenant_id=p_tenant and employee_id=rec.id and period_id=p_period and status='approved';
  allowances:=earn; adjearn:=normal_adj_earn+bonus_amt+overtime_amt; gross:=basic+earn+adjearn; taxable:=basic+taxable_extra+normal_adj_earn;
  insurable:=least(greatest(basic,coalesce(pr.minimum_insurable,0)),coalesce(pr.maximum_insurable,basic)); emp_pen:=case when pension_mode in ('active_contributor','legacy_special') and rec.pension_tier1_enabled then round(insurable*coalesce(pr.employee_rate,0)/100,2) else 0 end; er_pen:=case when pension_mode in ('active_contributor','legacy_special') and rec.pension_tier1_enabled then round(insurable*coalesce(pr.employer_rate,0)/100,2) else 0 end; tier1:=case when pension_mode in ('active_contributor','legacy_special') and rec.pension_tier1_enabled then round(insurable*coalesce(pr.tier1_total_rate,0)/100,2) else 0 end; tier2:=case when pension_mode in ('active_contributor','legacy_special') and rec.pension_tier2_enabled then round(insurable*coalesce(pr.tier2_total_rate,0)/100,2) else 0 end;
  org_pf_emp:=coalesce(nullif(cfg->>'employee_default_rate','')::numeric,0); org_pf_er:=coalesce(nullif(cfg->>'employer_default_rate','')::numeric,0);
  pf_emp_rate:=case when coalesce((cfg->>'employee_rate_variable')::boolean,false) and coalesce(rec.provident_employee_rate,0)>0 and rec.provident_employee_rate<>org_pf_emp then rec.provident_employee_rate else org_pf_emp end;
  pf_er_rate:=case when coalesce((cfg->>'employer_rate_variable')::boolean,false) and coalesce(rec.provident_employer_rate,0)>0 and rec.provident_employer_rate<>org_pf_er then rec.provident_employer_rate else org_pf_er end;
  tier3_ok:=coalesce((cfg->>'enabled')::boolean,false) and coalesce(cls.tier3_participation,rec.tier3_participation_mode,'not_participating')='participating' and
    case when pension_mode='pensioner_retiree' then coalesce((cfg->>'eligible_pensioner')::boolean,false) when rel='regular' then coalesce((cfg->>'eligible_regular')::boolean,true) when rel='fixed_term' then coalesce((cfg->>'eligible_fixed_term')::boolean,true) when rel='part_time' then coalesce((cfg->>'eligible_part_time')::boolean,true) when rel='temporary' then coalesce((cfg->>'eligible_temporary')::boolean,false) when rel='casual' then coalesce((cfg->>'eligible_casual')::boolean,false) when rel='intern' then coalesce((cfg->>'eligible_intern')::boolean,false) when rel='national_service' then coalesce((cfg->>'eligible_national_service')::boolean,false) when rel='locum' then coalesce((cfg->>'eligible_locum')::boolean,false) when rel='consultant' then coalesce((cfg->>'eligible_consultant')::boolean,false) else false end
    and (rec.provident_effective_from is null or rec.provident_effective_from<=pend) and (rec.provident_effective_to is null or rec.provident_effective_to>=pend);
  pf_emp:=case when tier3_ok then round(basic*pf_emp_rate/100,2) else 0 end; pf_er:=case when tier3_ok then round(basic*pf_er_rate/100,2) else 0 end;
  select coalesce(sum(case when rt.calculation_type='percent_income' then taxable*coalesce(rt.percent_rate,0)/100 else coalesce(er.approved_annual_amount,case when rt.calculation_type='per_unit_annual' then rt.annual_amount*least(er.units,coalesce(rt.max_units,er.units)) else rt.annual_amount end,0) end)/12,0) into relief from public.payroll_employee_reliefs er join public.payroll_relief_types rt on rt.id=er.relief_type_id where er.tenant_id=p_tenant and er.employee_id=rec.id and er.approved and er.relief_status='active' and er.tax_year=extract(year from pend)::int and er.effective_from<=pend and (er.effective_to is null or er.effective_to>=pend);
  chargeable:=greatest(taxable-emp_pen-least(pf_emp+pf_er,basic*coalesce(pr.provident_tax_relief_cap_rate,0)/100)-pretax-adjpretax-relief,0);
  if tax_mode='exempt' then tx:=0; ot_tax:=0; bonus_tax:=0;
  elsif tax_mode='casual_worker' then tx:=round(gross*0.05,2); ot_tax:=0; bonus_tax:=0;
  else
   tx:=case when tax_mode='non_resident' then round(chargeable*0.25,2) else public.payroll_progressive_tax(p_tenant,country,pend,chargeable) end;
   if tax_mode='non_resident' then ot_tax:=round(overtime_amt*0.20,2); bonus_tax:=round(bonus_amt*0.20,2);
   else
    if rec.staff_category='junior' and basic*12<=18000 then ot_tax:=round(least(overtime_amt,basic*0.5)*0.05+greatest(overtime_amt-basic*0.5,0)*0.10,2); else taxable:=taxable+overtime_amt; tx:=public.payroll_progressive_tax(p_tenant,country,pend,greatest(chargeable+overtime_amt,0)); ot_tax:=0; end if;
    bonus_concession:=least(bonus_amt,basic*12*0.15); bonus_tax:=round(bonus_concession*0.05,2); if bonus_amt>bonus_concession then tx:=tx+(public.payroll_progressive_tax(p_tenant,country,pend,chargeable+(bonus_amt-bonus_concession))-public.payroll_progressive_tax(p_tenant,country,pend,chargeable)); end if;
   end if; tx:=round(tx+ot_tax+bonus_tax,2);
  end if;
  select coalesce(sum(amount),0) into loans from public.payroll_adjustments where tenant_id=p_tenant and employee_id=rec.id and period_id=p_period and status='approved' and adjustment_type='loan';
  net:=gross-emp_pen-pf_emp-tx-ded-adjded-pretax-adjpretax;
  insert into public.payroll_run_employees(tenant_id,run_id,employee_id,employee_no,employee_name,basic_salary,other_earnings,gross_pay,employee_pension,employer_pension,tax,other_deductions,net_pay,taxable_income,chargeable_income,tier1_total,tier2_total,provident_employee,provident_employer,tax_relief,employer_cost,allowances_total,overtime_total,bonus_total,arrears_other_earnings,loan_deductions,other_nonloan_deductions) values(p_tenant,r,rec.id,rec.employee_no,concat_ws(' ',rec.first_name,rec.other_names,rec.last_name),basic,earn+adjearn,gross,emp_pen,er_pen,tx,ded+adjded+pretax+adjpretax,net,taxable,chargeable,tier1,tier2,pf_emp,pf_er,relief,gross+er_pen+pf_er,allowances,overtime_amt,bonus_amt,normal_adj_earn,loans,greatest(ded+adjded+pretax+adjpretax-loans,0)) returning id into re;
  insert into public.payroll_run_items(tenant_id,run_employee_id,component_code,component_name,component_type,amount,taxable,pensionable) values(p_tenant,re,'BASIC','Basic Salary','earning',basic,true,true),(p_tenant,re,'SSNIT-EE','Employee SSNIT','deduction',emp_pen,false,false),(p_tenant,re,'PAYE','PAYE / employment tax','deduction',tx,false,false);
  if pf_emp>0 then insert into public.payroll_run_items(tenant_id,run_employee_id,component_code,component_name,component_type,amount,taxable,pensionable) values(p_tenant,re,'TIER3-EE','Tier 3 / PF Employee','deduction',pf_emp,false,false); end if;
  if relief>0 then insert into public.payroll_run_items(tenant_id,run_employee_id,component_code,component_name,component_type,amount,taxable,pensionable) values(p_tenant,re,'RELIEF','Approved Tax Relief','relief',relief,false,false); end if;
 end loop;
 update public.payroll_runs prun set status='calculated',employee_count=x.cnt,gross_total=x.gross,deduction_total=x.ded,employee_pension_total=x.ep,employer_pension_total=x.erp,tax_total=x.tax,net_total=x.net from (select count(*) cnt,coalesce(sum(gross_pay),0) gross,coalesce(sum(other_deductions),0) ded,coalesce(sum(employee_pension),0) ep,coalesce(sum(employer_pension),0) erp,coalesce(sum(tax),0) tax,coalesce(sum(net_pay),0) net from public.payroll_run_employees where run_id=r)x where prun.id=r;
 update public.payroll_periods set status='review' where id=p_period; return r;
end $$;
grant execute on function public.payroll_calculate_run(uuid,uuid) to authenticated;
